241	    @Transactional
242	    public Xzj27 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
243	                                          boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
244	        try {
245	
246	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
247	
248	
249	            Xrd81 buyer = userQueryService.findByEmail(buyerEmail);
250	
251	
252	            Xzz58 saleBid = getSaleBidAndValidate(saleBidId);
253	            Xgg74 sale = saleBid.getSale();
254	
255	
256	            Xdg64 order = orderCommandService.createInstantOrder(
257	                    buyer,
258	                    saleBid,
259	                    addressId,
260	                    isWarehouseStorage,
261	                    paymentRequest
262	            );
263	
264	
265	            Xzj27 orderBid = createInstantOrderBid(order, saleBid, sale);
266	
267	            return orderBid;
268	        } catch (Exception e) {
269	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
270	            return null;
271	        }
272	    }
