445	                acknowledgment.acknowledge();
446	                return;
447	            }
448	
449	
450	            Xdg64 order = orderRepository.findById(event.getOrderId())
451	                    .orElseThrow(() -> new IllegalArgumentException(
452	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
