493	            @Payload Xmr97Event event,
494	            Acknowledgment acknowledgment) {
495	
496	        try {
497	            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
498	                    event.getOrderId(), event.getRetryCount());
499	
500	            if (event.isMaxRetryExceeded()) {
501	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
502	                        event.getOrderId(), event.getRetryCount());
503	
504	
505	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
506	                acknowledgment.acknowledge();
507	                return;
508	            }
509	
510	
511	            if (isOrderAlreadyProcessed(event.getOrderId())) {
512	                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
513	                acknowledgment.acknowledge();
514	                return;
515	            }
516	
517	
518	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
519	
520	
521	            handleOrderProcessingEvent(event, acknowledgment);
522	
523	        } catch (InterruptedException e) {
524	            Thread.currentThread().interrupt();
525	            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
526	            acknowledgment.acknowledge();
527	        } catch (Exception e) {
528	            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
529	                    event.getOrderId(), e.getMessage(), e);
530	            acknowledgment.acknowledge();
531	        }
532	    }
