626	    private void handleOrderProcessingFailure(Xmr97Event event, Exception error, Acknowledgment acknowledgment) {
627	        try {
628	
629	            if (isRetryableError(error)) {
630	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
631	                orderEventProducer.sendOrderRetryEvent(event);
632	            } else {
633	                log.error("재시도 불가능한 오류로 주문 처리 실패: 주문ID={}, 오류={}",
634	                        event.getOrderId(), error.getMessage());
635	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), error.getMessage());
636	            }
637	
638	            acknowledgment.acknowledge();
639	
640	        } catch (Exception e) {
641	            log.error("주문 처리 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
642	            acknowledgment.acknowledge();
643	        }
644	    }
